                            for (let i = 0; i < targetArray.length; i++) {
                                const v = targetArray[i];
                                if (Number.isFinite(v) && v > maxIndex) maxIndex = v;
                            }
                            const IndexCtor = maxIndex <= 65535 ? (globalScope.Uint16Array || Uint16Array) : (globalScope.Uint32Array || Uint32Array);
